class BytesIOCopy:
    """A binary stream that copies everything written to it to another
    stream (``copy_to``).

    Unlike :class:`io.BytesIO`, this is backed by a real (anonymous)
    temporary file, so it has a working file descriptor. This lets code
    invoked through :class:`CliRunner` pass ``sys.stdout``/``sys.stderr``
    to APIs such as :func:`subprocess.run` that require a real file
    object.

    .. versionadded:: 8.2

    .. versionchanged:: 8.3
        Backed by a real file so ``fileno()`` works.
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file: t.BinaryIO = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)


